import React, { Component } from 'react';
import PropTypes from 'prop-types';
import { Button, Col, Form, Row, Collapse, Modal } from 'react-bootstrap';
import { Formik } from 'formik';
import DraggableModalDialog from '@jsroot/components/DraggableModalDialog';
import FormikErrorMessage from '@jsroot/components/FormikErrorMessage';
import ResponseMessage from '@jsroot/components/ResponseMessage';
import LangHelper from '@jsroot/common/langHelper';
import DateTimeService from '@jsroot/common/dateTimeService';
import SweetModalDialog from '@jsroot/components/SweetModalDialog';
import DataService from '@jsroot/common/dataService';
import Site from '@jsroot/common/site';
import MultipleSelect from '@jsroot/components/multiple-select/index';
import DatePicker from '@jsroot/components/date-picker/index';
import CkEditor from '@jsroot/components/ckeditor/index';
import AutoComplete from '@jsroot/components/AutoComplete';
import { validateNoOfInquiry } from '../../common.functions';
import SelectWithSearch from '@jsroot/components/SelectWithSearch';
import { getInitFormik, getValidateFormik } from '../common.functions.js';
import {
    getSubCategories, getSubProducts, getBetTypes, getSubjectOnChangeCategories,
    getProductParams, getCategoryParams
} from '@jsroot/common/shareScripts';

export class EditMultipleLogs extends Component {
    static propTypes = {
        feedbackArr: PropTypes.array.isRequired,
        onClose: PropTypes.func.isRequired
    };

    static defaultProps = {
        feedbackArr: [],
        onClose: function () {
            // nothing
        }
    };

    constructor(props) {
        super(props);
        this.state = {
            feedbackArr: props.feedbackArr,
            communication: null,
            communicationToolOptions: [],
            mainCategoryOptions: [],
            subCategoryOptions: [],
            productOptions: [],
            subProductOptions: [],
            betTypeOptions: [],
            sitesOptions: [],
            feedbackSubjectTemplates: [],
            confirmEditMultipleLogsDialog: { show: false },
            settings: null,
            hasReviewFeedbackPermission: false,
            editResult: null
        };
    }

    async componentDidMount() {
        const id = this.props.feedbackArr[0].feedbackId;
        const url = Site.resolveClientUrl(`MultipleLogs/GetLogSettingByFeedbackId/${id}`);
        await DataService.getDataAsync(url).then(response => {
            const data = response.data;
            const communicationSettings = this.getCommunicationSettings(data.communicationLog, data.settings);
            const extensionOptions = data.settings.extensions.map(item => {
                return {
                    id: item.id,
                    value: item.value,
                    checked: communicationSettings.extensionIds.includes(item.id)
                };
            });
            const sitesOptions = data.settings.sites;
            const communicationToolOptions = data.settings.communicationTools.map(item => {
                return {
                    id: item.id,
                    name: item.name,
                    checked: communicationSettings.communicationToolIds.includes(item.id)
                };
            });
            const mainCategoryOptions = data.settings.mainCategories.map(item => {
                return {
                    mainCategoryID: item.mainCategoryID,
                    name: item.name,
                    checked: communicationSettings.mainCategoryIds.includes(item.mainCategoryID)
                };
            });
            const subCategories = data.settings.subCategories.filter(item => communicationSettings.mainCategoryIds.includes(item.mainCategoryID));
            const subCategoryOptions = subCategories.map(item => {
                return {
                    subCategoryId: item.subCategoryId,
                    name: item.name,
                    checked: communicationSettings.subCategoryIds.includes(item.subCategoryId)
                };
            });

            const productOptions = data.settings.products.map(item => {
                return {
                    id: item.id,
                    value: item.value,
                    checked: communicationSettings.productIds.includes(item.id)
                };
            });
            const subProducts = data.settings.subProducts.filter(item => communicationSettings.productIds.includes(item.parentId) && item.parentId !== 0);
            const subProductOptions = subProducts.map(sub => {
                return {
                    id: sub.id,
                    value: sub.value,
                    checked: communicationSettings.productIds.includes(sub.id)
                };
            });
            const bettypes = data.settings.bettypes.filter(item => communicationSettings.subProductIds.includes(item.parentId) && item.parentId !== 0);
            const betTypeOptions = bettypes.map(item => {
                return {
                    id: item.id,
                    value: item.value,
                    checked: communicationSettings.betTypeIds.includes(item.id)
                };
            });

            this.setState({
                communication: this.initFormik(data.communicationLog, data.settings),
                settings: data.settings,
                hasReviewFeedbackPermission: data.hasReviewFeedbackPermission,
                extensionOptions,
                productOptions,
                subProductOptions,
                betTypeOptions,
                communicationToolOptions,
                mainCategoryOptions,
                subCategoryOptions,
                sitesOptions
            });
        });
    }

    getCommunicationSettings = (communicationLog, settings) => {
        const communicationLogSettings = communicationLog.settings;
        const siteInfos = [];

        settings.sites.forEach(site => {
            const siteFilter = site.childSites.filter(item => item.id === communicationLog.siteId);
            if (siteFilter.length > 0) {
                siteInfos.push(siteFilter[0]);
            }
        });

        const selectedExtensionIds = [],
            selectedProductIds = [],
            selectedSubProductIds = [],
            selectedBetTypeIds = [],
            selectedCommunicationToolIds = [],
            selectedMainCategoryIds = [],
            selectedSubCategoryIds = [];
        communicationLogSettings.forEach(x => {
            switch (x.settingType) {
                case 'Product':
                    if (x.settingId !== settings.productNA?.id) {
                        selectedProductIds.push(x.settingId);
                    }
                    if (x.subSettingId !== settings.subProductNA?.id) {
                        selectedSubProductIds.push(x.subSettingId);
                    }
                    if (x.subSettingIdLevel3 !== settings.bettypeNA?.id) {
                        selectedBetTypeIds.push(x.subSettingIdLevel3);
                    }
                    break;
                case 'Category':
                    selectedMainCategoryIds.push(x.settingId);
                    selectedSubCategoryIds.push(x.subSettingId);
                    break;
                case 'Communication':
                    if (x.settingId !== settings.communicationToolNA?.id) {
                        selectedCommunicationToolIds.push(x.settingId);
                    }
                    break;
                case 'Station':
                    if (x.settingId !== settings.extensionNA?.id) {
                        selectedExtensionIds.push(x.settingId);
                    }
                    break;
            }
        });

        return {
            extensionIds: selectedExtensionIds,
            communicationToolIds: selectedCommunicationToolIds,
            mainCategoryIds: selectedMainCategoryIds,
            subCategoryIds: selectedSubCategoryIds,
            productIds: selectedProductIds,
            subProductIds: selectedSubProductIds,
            betTypeIds: selectedBetTypeIds,
            siteInfos: siteInfos
        };
    };

    onChangeMainCategory = (setFieldValue, selectedCategories, selectedSubCategoryIds, subject) => {
        const settings = this.state.settings;
        const subjectChange = getSubjectOnChangeCategories(selectedCategories ? selectedCategories.split(',') : [],
            subject,
            settings.mainCategories);
        setFieldValue('mainCategoryIds', selectedCategories);
        setFieldValue('subject', subjectChange);
        if (selectedCategories) {
            const subCategoryIds = selectedSubCategoryIds.length > 0 ? selectedSubCategoryIds.split(',') : [];
            const subCategoryOptions = getSubCategories(selectedCategories.split(','), settings.subCategories, subCategoryIds, false);
            this.setState({ subCategoryOptions });
        } else {
            this.setState({ subCategoryOptions: [] });
            setFieldValue('subCategoryIds', '');
        }
    };

    onChangeProduct = (setFieldValue, selectedProductIds, selectedSubProductIds) => {
        setFieldValue('productIds', selectedProductIds);
        if (selectedProductIds) {
            const subProductIds = selectedSubProductIds.length > 0 ? selectedSubProductIds.split(',') : [];
            const subProducts = getSubProducts(selectedProductIds.split(','), this.state.settings.subProducts, subProductIds, false);
            this.setState({ subProductOptions: subProducts });
        } else {
            this.setState({
                subProductOptions: [],
                betTypeOptions: []
            });
            setFieldValue('subProductIds', '');
            setFieldValue('betTypeIds', '');
        }
    };

    onChangeSubProduct = (setFieldValue, selectedSubProductIds, selectedBetTypeIds) => {
        setFieldValue('subProductIds', selectedSubProductIds);
        if (selectedSubProductIds) {
            const betTypeIds = selectedBetTypeIds.length > 0 ? selectedBetTypeIds.split(',') : [];
            const betTypes = getBetTypes(selectedSubProductIds.split(','), this.state.settings.bettypes, betTypeIds, false);
            this.setState({ betTypeOptions: betTypes });
        } else {
            this.setState({ betTypeOptions: [] });
            setFieldValue('betTypeIds', '');
        }
    };

    onGetFeedbackSubjectTemplates = Site.debounce(async searchText => {
        if (searchText.length >= 2) {
            const url = Site.resolveClientUrl('Common/GetFeedbackSubjectTemplate');
            await DataService.getDataAsync(url, { searchText }).then(response => {
                this.setState({ feedbackSubjectTemplates: response.data });
            });
        } else {
            this.setState({ feedbackSubjectTemplates: [] });
        }
    });

    handleCheckAll = (checks, setFieldValue, event) => {
        for (const [key] of Object.entries(checks)) {
            setFieldValue(`isCheck.${key}`, event.target.checked);
        }
    };

    getExtensionParams = (selectedExtensionIds, extensionNA) => {
        let extensionIds = [];
        if (selectedExtensionIds.length > 0) {
            extensionIds = selectedExtensionIds.split(',');
        }

        if (extensionIds.length === 0 && extensionNA !== null && extensionNA.id !== undefined) {
            extensionIds.push(extensionNA.id);
        }

        return extensionIds.join(',');
    };

    renderAutoGenerated = (values, handleChange, setFieldValue) => {
        return (
            <div className="panel-group border-bottom-0">
                <Form.Group as={Row} className="panel-title justify-content-between">
                    <Form.Label>{LangHelper.getResource('AutoGenerated')}</Form.Label>
                    <input className="ml-2" type='checkbox'
                        name='isCheck.autoGenerated'
                        onChange={event => {
                            setFieldValue('isCheck.autoGenerated', event.target.checked);
                            setFieldValue('isCheck.description', event.target.checked);
                        }}
                        checked={values.isCheck.autoGenerated}
                    />
                </Form.Group>
                <div className="panel-content">
                    <Form.Control as="textarea" rows={3} className="shadow-none"
                        name="autoGenerated" disabled={!values.isCheck.autoGenerated}
                        value={values.autoGenerated} onChange={handleChange}
                    />
                </div>
            </div>
        );
    };

    renderDescription = (values, touched, errors, setFieldValue) => {
        return (
            <div className="panel-group border-bottom-0">
                <Form.Group as={Row} className="panel-title justify-content-between">
                    <Form.Label className="required">{LangHelper.getResource('Remark')}</Form.Label>
                    <input type='checkbox'
                        name='isCheck.description'
                        disabled
                        checked={values.isCheck.description}
                    />
                </Form.Group>
                <div className="panel-content">
                    {
                        !values.isCheck.autoGenerated &&
                        <div>
                            <div dangerouslySetInnerHTML={{ __html: values.description }} />
                        </div>
                    }
                    {
                        values.isCheck.autoGenerated &&
                        <CkEditor isInvalid={touched.description && errors.description}
                            data={values.description} username={window.currentUsername}
                            onChange={value => setFieldValue('description', value)}
                        />
                    }
                </div>
            </div>
        );
    };

    renderSolution = (values, touched, errors, setFieldValue) => {
        return (
            <div className="panel-group border-bottom-0">
                <Form.Group as={Row} className="panel-title justify-content-between"
                    aria-controls="collapse-expand-solution"
                >
                    <Form.Label className="required">{LangHelper.getResource('Solution')}</Form.Label>
                    <input type='checkbox'
                        name='isCheck.solution'
                        onChange={event => setFieldValue('isCheck.solution', event.target.checked)}
                        checked={values.isCheck.solution}
                    />
                </Form.Group>
                <div className="panel-content">
                    {
                        !values.isCheck.solution &&
                        <div dangerouslySetInnerHTML={{ __html: values.solution }} />
                    }
                    {
                        values.isCheck.solution &&
                        <CkEditor isInvalid={touched.solution && errors.solution}
                            data={values.solution} username={window.currentUsername}
                            onChange={value => setFieldValue('solution', value)}
                        />
                    }
                </div>
            </div>
        );
    };

    renderReview = (values, touched, errors, setFieldValue) => {
        return (
            <div className="panel-group">
                <Form.Group as={Row} className={`panel-title ${!values.isCheck.reviewed ? 'border-bottom-0' : ''}`}>
                    <Form.Label className={values.reviewed ? 'required' : ''}>{LangHelper.getResource('Review')}</Form.Label>
                    <input className="ml-2" type='checkbox'
                        onChange={event => setFieldValue('isCheck.reviewed', event.target.checked)}
                        checked={values.isCheck.reviewed}
                    />
                    <span className="font-italic ml-2">
                        {values.reviewerName ? LangHelper.formatString(LangHelper.getResource('ReviewerBy'), values.reviewerName, values.solveDate) : ''}
                    </span>
                </Form.Group>
                <Collapse in={values.isCheck.reviewed}>
                    <div className="panel-content">
                        <CkEditor isInvalid={touched.review && errors.review}
                            data={values.review} username={window.currentUsername}
                            onChange={value => setFieldValue('review', value)}
                        />
                    </div>
                </Collapse>
            </div>
        );
    };

    renderDropdownDetail = (errors, values, handleChange, touched, setFieldValue) => {
        const { settings, mainCategoryOptions, subCategoryOptions, productOptions, subProductOptions, betTypeOptions, sitesOptions } = this.state;
        const { statuses, roles } = settings;
        return (
            <div>
                <Form.Group as={Row}>
                    <Form.Label column sm="2" md="2" htmlFor="mainCategoryIds" className="required">
                        {LangHelper.getResource('MainCategory')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <div className={`pr-2 ${this.isDisabledField(values.isCheck.mainCategory)}`}>
                            <MultipleSelect
                                isInvalid={touched.mainCategoryIds && errors.mainCategoryIds}
                                dataSource={mainCategoryOptions}
                                keyField='mainCategoryID' valueField='name'
                                hasAllOption={mainCategoryOptions.length > 0}
                                isAllTextShown={mainCategoryOptions.length > 0}
                                hasSearchBox isNAOption
                                maxDisplayItemCount={1}
                                onChange={(currentItem, selectedItemsKey) => {
                                    this.onChangeMainCategory(setFieldValue, selectedItemsKey, values.subCategoryIds, values.subject);
                                }}
                            />
                        </div>
                        <input type='checkbox'
                            name='isCheck.mainCategory'
                            onChange={event => {
                                setFieldValue('isCheck.mainCategory', event.target.checked);
                                setFieldValue('isCheck.subCategory', event.target.checked);
                            }}
                            checked={values.isCheck.mainCategory}
                        />
                    </Col>
                    <Form.Label column sm="2" md="2" htmlFor="subCategoryIds" className="required">
                        {LangHelper.getResource('SubCate')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <div className={`pr-2 ${this.isDisabledField(values.isCheck.subCategory)}`}>
                            <MultipleSelect
                                isInvalid={touched.subCategoryIds && errors.subCategoryIds}
                                dataSource={subCategoryOptions}
                                keyField='subCategoryId' valueField='name'
                                hasAllOption={subCategoryOptions.length > 0}
                                isAllTextShown={subCategoryOptions.length > 0}
                                hasSearchBox isNAOption
                                maxDisplayItemCount={1}
                                onChange={(currentItem, selectedItemsKey) => {
                                    setFieldValue('subCategoryIds', selectedItemsKey);
                                }}
                            />
                        </div>
                        <input type='checkbox'
                            disabled
                            name='isCheck.subCategory'
                            checked={values.isCheck.subCategory}
                        />
                    </Col>
                </Form.Group>
                <Form.Group as={Row}>
                    <Form.Label column sm="2" md="2" htmlFor="product">
                        {LangHelper.getResource('Product')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <div className={`pr-2 ${this.isDisabledField(values.isCheck.product)}`}>
                            <MultipleSelect
                                dataSource={productOptions}
                                keyField='id' valueField='value'
                                hasAllOption={productOptions.length > 0}
                                isAllTextShown={productOptions.length > 0}
                                hasSearchBox isNAOption
                                maxDisplayItemCount={1}
                                onChange={(currentItem, selectedItemsKey) => {
                                    this.onChangeProduct(setFieldValue, selectedItemsKey, values.subProductIds);
                                }}
                            />
                        </div>
                        <input type='checkbox'
                            name='isCheck.product'
                            onChange={event => {
                                setFieldValue('isCheck.product', event.target.checked);
                                setFieldValue('isCheck.subProduct', event.target.checked);
                                setFieldValue('isCheck.betType', event.target.checked);
                            }}
                            checked={values.isCheck.product}
                        />
                    </Col>
                    <Form.Label column sm="2" md="2" htmlFor="subProductIds">
                        {LangHelper.getResource('SubProduct')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <div className={`pr-2 ${this.isDisabledField(values.isCheck.product)}`}>
                            <MultipleSelect
                                dataSource={subProductOptions}
                                keyField='id' valueField='value'
                                hasAllOption={subProductOptions.length > 0}
                                isAllTextShown={subProductOptions.length > 0}
                                hasSearchBox isNAOption
                                maxDisplayItemCount={1}
                                onChange={(currentItem, selectedItemsKey) => {
                                    this.onChangeSubProduct(setFieldValue, selectedItemsKey, values.betTypeIds);
                                }}
                            />
                        </div>
                        <input type='checkbox'
                            name='isCheck.subProduct'
                            disabled
                            onChange={event => setFieldValue('isCheck.subProduct', event.target.checked)}
                            checked={values.isCheck.subProduct}
                        />
                    </Col>
                </Form.Group>
                <Form.Group as={Row}>
                    <Form.Label column sm="2" md="2" htmlFor="statusId">
                        {LangHelper.getResource('Status')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <Form.Control as="select" size="sm" className={`shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.status)}`}
                            id="statusId" name="statusId"
                            value={values.statusId} onChange={handleChange}
                        >
                            {statuses.map(item => <option key={item.statusId} value={item.statusId}>{item.name}</option>)}
                        </Form.Control>
                        <input type='checkbox'
                            name='isCheck.status'
                            onChange={event => setFieldValue('isCheck.status', event.target.checked)}
                            checked={values.isCheck.status}
                        />
                    </Col>
                    <Form.Label column sm="2" md="2" htmlFor="betTypeIds">
                        {LangHelper.getResource('BetType')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <div className={`pr-2 ${this.isDisabledField(values.isCheck.product)}`}>
                            <MultipleSelect
                                dataSource={betTypeOptions}
                                keyField='id' valueField='value'
                                hasAllOption={betTypeOptions.length > 0}
                                isAllTextShown={betTypeOptions.length > 0}
                                hasSearchBox isNAOption
                                maxDisplayItemCount={1}
                                onChange={(currentItem, selectedItemsKey) => {
                                    setFieldValue('betTypeIds', selectedItemsKey);
                                }}
                            />
                        </div>
                        <input type='checkbox'
                            name='isCheck.betType'
                            disabled
                            onChange={event => setFieldValue('isCheck.betType', event.target.checked)}
                            checked={values.isCheck.betType}
                        />
                    </Col>
                </Form.Group>
                <Form.Group as={Row}>
                    <Form.Label column sm="2" md="2" htmlFor="roleId">
                        {LangHelper.getResource('Role')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <Form.Control as="select" size="sm" className={`shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.role)}`}
                            id='roleId' name='roleId'
                            value={values.roleId} onChange={handleChange}
                        >
                            {roles.map(item => <option key={item.id} value={item.id}>{item.value}</option>)}
                        </Form.Control>
                        <input type='checkbox'
                            name='isCheck.role'
                            onChange={event => setFieldValue('isCheck.role', event.target.checked)}
                            checked={values.isCheck.role}
                        />
                    </Col>
                    <Form.Label column sm="2" md="2" htmlFor="siteInfo" >
                        {LangHelper.getResource('Site')}
                    </Form.Label>
                    <Col column sm="4" md="4" className="d-flex">
                        <div className={`mr-2 select-width-sm ${this.isDisabledField(values.isCheck.site)}`}>
                            <SelectWithSearch
                                className='basic-single'
                                options={sitesOptions}
                                value={values.siteInfo.id}
                                name={values.siteInfo.name}
                                OnChangeValue={value => setFieldValue('siteInfo', value)}
                            />
                        </div>
                        <input type='checkbox'
                            name='isCheck.site'
                            onChange={event => setFieldValue('isCheck.site', event.target.checked)}
                            checked={values.isCheck.site}
                        />
                    </Col>
                </Form.Group>
            </div>
        );
    };

    renderSelectOptions = (values, handleChange, setFieldValue) => {
        const { countries, licenseeTypes } = this.state.settings;
        return (
            <div>
                <Form.Group as={Row}>
                    <Form.Label column sm="2" md="2" htmlFor="countryId">
                        {LangHelper.getResource('Country')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <Form.Control as="select" size="sm" className={`shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.country)}`}
                            id="countryId" name="countryId"
                            value={values.countryId} onChange={handleChange}
                        >
                            {countries.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}
                        </Form.Control>
                        <input type='checkbox'
                            name='isCheck.country'
                            onChange={event => setFieldValue('isCheck.country', event.target.checked)}
                            checked={values.isCheck.country}
                        />
                    </Col>
                    <Form.Label column sm="2" md="2" htmlFor="licenseeId">
                        {LangHelper.getResource('LicenseeType')}
                    </Form.Label>
                    <Col sm="4" md="4" className="d-flex">
                        <Form.Control as="select" size="sm" className={`shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.licensee)}`}
                            id="licenseeId" name="licenseeId"
                            value={values.licenseeId} onChange={handleChange}
                        >
                            {licenseeTypes.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}
                        </Form.Control>
                        <input type='checkbox'
                            name='isCheck.licensee'
                            onChange={event => setFieldValue('isCheck.licensee', event.target.checked)}
                            checked={values.isCheck.licensee}
                        />
                    </Col>
                </Form.Group>
            </div>
        );
    };

    isDisabledField = checked => {
        if (!checked) {
            return 'disabled-filed';
        }
        return '';
    };

    renderMultipleLogs = (errors, values, handleChange, touched, setFieldValue) => {
        const { settings, extensionOptions, communicationToolOptions, feedbackSubjectTemplates } = this.state;

        const { responses, languages } = settings;
        return (
            <div>
                <div className="panel-group border-bottom-0">
                    <div className="panel-content">
                        <Form.Group as={Row}>
                            <Form.Label column sm="2" md="2">
                                {LangHelper.getResource('Listofcustomers')}
                            </Form.Label>
                            <Col sm="8" md="8">
                                <Form.Control type="text" size="sm" value={values.usernames}
                                    name="usernames" id="usernames"
                                    className="shadow-none" autoComplete="off"
                                    disabled
                                    isInvalid={touched.usernames && errors.usernames}
                                    onChange={handleChange}
                                />
                            </Col>
                            <Col sm="2" md="2" className="select-all-field">
                                <Form.Label>
                                    {LangHelper.getResource('SelectAll')}
                                </Form.Label>
                                <input className="ml-2" type='checkbox'
                                    name='isCheck.checkAll'
                                    onChange={event => this.handleCheckAll(values.isCheck, setFieldValue, event)}
                                    checked={values.isCheck.checkAll}
                                />
                            </Col>
                        </Form.Group>
                        <Form.Group as={Row}>
                            <Form.Label column sm="2" md="2" htmlFor="startTime">
                                {LangHelper.getResource('StartTime')}
                            </Form.Label>
                            <Col sm="4" md="4" className="d-flex">
                                <div className={`react-datepicker-wrapper-container form-control-wrapper pr-2 ${this.isDisabledField(values.isCheck.startTime)}`}>
                                    <DatePicker timeInputLabel="Time:" showTimeInput
                                        selected={values.startTime}
                                        peekNextMonth showMonthDropdown showYearDropdown dropdownMode="select"
                                        onChange={value => setFieldValue('startTime', value)}
                                    />
                                </div>
                                <input type='checkbox'
                                    name='isCheck.startTime'
                                    onChange={event => setFieldValue('isCheck.startTime', event.target.checked)}
                                    checked={values.isCheck.startTime}
                                />
                            </Col>
                            <Form.Label column sm="2" md="2" htmlFor="extensionIds">
                                {LangHelper.getResource('Ext')}
                            </Form.Label>
                            <Col sm="4" md="4" className="d-flex">
                                <div className={`pr-2 ${this.isDisabledField(values.isCheck.ext)}`}>
                                    <MultipleSelect
                                        hasAllOption={extensionOptions.length > 0}
                                        isAllTextShown={extensionOptions.length > 0}
                                        dataSource={extensionOptions}
                                        keyField='id' valueField='value'
                                        hasSearchBox isNAOption
                                        onChange={(currentItem, selectedItemsKey) => {
                                            setFieldValue('extensionIds', selectedItemsKey);
                                        }}
                                    />
                                </div>
                                <input type='checkbox'
                                    name='isCheck.ext'
                                    onChange={event => setFieldValue('isCheck.ext', event.target.checked)}
                                    checked={values.isCheck.ext}
                                />
                            </Col>
                        </Form.Group>
                        <Form.Group as={Row}>
                            <Form.Label column sm="2" md="2" htmlFor="endTime">
                                {LangHelper.getResource('EndTime')}
                            </Form.Label>
                            <Col sm="4" md="4" className="d-flex">
                                <div className={`react-datepicker-wrapper-container form-control-wrapper pr-2 ${this.isDisabledField(values.isCheck.endTime)}`}>
                                    <DatePicker timeInputLabel="Time:" showTimeInput
                                        selected={values.endTime}
                                        peekNextMonth showMonthDropdown showYearDropdown dropdownMode="select"
                                        onChange={value => setFieldValue('endTime', value)}
                                    />
                                </div>
                                <input type='checkbox'
                                    name='isCheck.endTime'
                                    onChange={event => setFieldValue('isCheck.endTime', event.target.checked)}
                                    checked={values.isCheck.endTime}
                                />
                            </Col>
                            <Form.Label column sm="2" md="2" htmlFor="responseId">
                                {LangHelper.getResource('Response')}
                            </Form.Label>
                            <Col sm="4" md="4" className='d-flex'>
                                <Form.Control as="select" size="sm" className={`shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.response)}`}
                                    id="responseId" name="responseId"
                                    value={values.responseId} onChange={handleChange}
                                    disabled={!values.isCheck.response}
                                >
                                    {responses.map(item => <option key={item.id} value={item.id}>{item.value}</option>)}
                                </Form.Control>
                                <input type='checkbox'
                                    name='isCheck.response'
                                    onChange={event => setFieldValue('isCheck.response', event.target.checked)}
                                    checked={values.isCheck.response}
                                />
                            </Col>
                        </Form.Group>
                        <Form.Group as={Row}>
                            <Form.Label column sm="2" md="2" htmlFor="communicationToolId" className="required">
                                {LangHelper.getResource('Communication')}
                            </Form.Label>
                            <Col sm="4" md="4" className="d-flex">
                                <div className={`pr-2 ${this.isDisabledField(values.isCheck.communication)}`}>
                                    <MultipleSelect
                                        isInvalid={touched.communicationToolIds && errors.communicationToolIds}
                                        dataSource={communicationToolOptions}
                                        keyField='id' valueField='name'
                                        hasAllOption={communicationToolOptions.length > 0}
                                        isAllTextShown={communicationToolOptions.length > 0}
                                        hasSearchBox isNAOption
                                        onChange={(currentItem, selectedItemsKey) => {
                                            setFieldValue('communicationToolIds', selectedItemsKey);
                                        }}
                                    />
                                </div>
                                <input type='checkbox'
                                    name='isCheck.communication'
                                    onChange={event => setFieldValue('isCheck.communication', event.target.checked)}
                                    checked={values.isCheck.communication}
                                />
                            </Col>
                            <Form.Label column sm="2" md="2" htmlFor="languageId" className="required">
                                {LangHelper.getResource('Language')}
                            </Form.Label>
                            <Col sm="4" md="4" className="d-flex">
                                <Form.Control as="select" size="sm" className={`shadow-none shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.language)}`}
                                    isInvalid={touched.languageId && errors.languageId}
                                    id="languageId" name="languageId"
                                    value={values.languageId} onChange={handleChange}
                                >
                                    {languages.map(item => <option key={item.languageId} value={item.languageId}>{item.name}</option>)}
                                </Form.Control>
                                <input type='checkbox'
                                    name='isCheck.language'
                                    onChange={event => setFieldValue('isCheck.language', event.target.checked)}
                                    checked={values.isCheck.language}
                                />
                            </Col>
                        </Form.Group>
                        {this.renderDropdownDetail(errors, values, handleChange, touched, setFieldValue)}
                        {this.renderSelectOptions(values, handleChange, setFieldValue)}
                        <Form.Group as={Row}>
                            <Form.Label column sm="2" md="2" htmlFor="noInquiries">
                                {LangHelper.getResource('NoOfInquiries')}
                            </Form.Label>
                            <Col sm="4" md="4" className="d-flex">
                                <Form.Control size="sm" type="number" min={1} max={3200}
                                    value={values.noInquiries} id="noInquiries" name="noInquiries"
                                    className={`shadow-none select-width-sm mr-2 ${this.isDisabledField(values.isCheck.inquiry)}`} autoComplete="off"
                                    onInput={validateNoOfInquiry} onChange={handleChange}
                                />
                                <input type='checkbox'
                                    name='isCheck.inquiry'
                                    onChange={event => setFieldValue('isCheck.inquiry', event.target.checked)}
                                    checked={values.isCheck.inquiry}
                                />
                            </Col>
                        </Form.Group>
                        <Form.Group as={Row}>
                            <Form.Label column sm="2" md="2" htmlFor="subject" className="required">
                                {LangHelper.getResource('Subject')}
                            </Form.Label>
                            <Col sm="8" md="8" className="d-flex">
                                <div className={`${this.isDisabledField(values.isCheck.subject)} w-100`}>
                                    <AutoComplete isInvalid={touched.subject && errors.subject}
                                        value={values.subject}
                                        options={feedbackSubjectTemplates} displayField="subject"
                                        onChange={value => setFieldValue('subject', value)}
                                        onInputChange={this.onGetFeedbackSubjectTemplates}
                                    />
                                </div>
                                <input className="ml-2" type='checkbox'
                                    name='isCheck.subject'
                                    onChange={event => setFieldValue('isCheck.subject', event.target.checked)}
                                    checked={values.isCheck.subject}
                                />
                            </Col>
                        </Form.Group>
                    </div>
                </div>
                {this.renderAutoGenerated(values, handleChange, setFieldValue)}
                {this.renderDescription(values, touched, errors, setFieldValue)}
                {this.renderSolution(values, touched, errors, setFieldValue)}
                {this.renderReview(values, touched, errors, setFieldValue)}
            </div>
        );
    };

    renderForm = ({
        errors,
        values,
        handleChange,
        touched,
        setFieldValue,
        handleSubmit,
        isSubmitting
    }) => {
        return (
            <Form noValidate onSubmit={handleSubmit}>
                <Modal.Body>
                    <FormikErrorMessage touched={touched} errors={errors} fieldNames={Object.keys(values)} />
                    {
                        this.state.editResult &&
                        <ResponseMessage isSuccessful={this.state.editResult.isSuccessful}
                            message={this.state.editResult.message || LangHelper.getResource('UpdateMultipleLogsSuccessfully')}
                        />
                    }
                    {
                        this.renderMultipleLogs(errors, values, handleChange, touched, setFieldValue)
                    }
                </Modal.Body >
                <Modal.Footer>
                    <Button size="sm" type="submit" variant="primary" disabled={isSubmitting}>
                        {LangHelper.getResource('Save')}
                    </Button>
                    <Button size="sm" type="button" variant="primary" onClick={() => this.props.onClose(false)}>
                        {LangHelper.getResource('Cancel')}
                    </Button>
                </Modal.Footer>
            </Form>
        );
    };

    handleSubmit = (values, { setSubmitting }) => {
        setSubmitting(true);
        const params = {
            listFeedbackId: this.state.feedbackArr.map(x => x.feedbackId).join(' ,'),
            countryId: values.countryId,
            isUpdateCountryId: values.isCheck.country,
            siteId: values.siteInfo.id,
            isUpdateSiteId: values.isCheck.site,
            subject: values.subject,
            isUpdateSubject: values.isCheck.subject,
            languageId: parseInt(values.languageId, 10),
            isUpdateLanguageID: values.isCheck.language,
            feedbackDate: DateTimeService.toLongDateTimeFormat(DateTimeService.toServerDateTime(values.startTime)),
            isUpdateFeedbackDate: values.isCheck.startTime,
            resolutionDate: DateTimeService.toLongDateTimeFormat(DateTimeService.toServerDateTime(values.endTime)),
            isUpdateResolutionDate: values.isCheck.endTime,
            stationId: this.getExtensionParams(values.extensionIds, this.state.settings.extensionNA),
            isUpdateStationId: values.isCheck.ext,
            roleId: values.roleId,
            isUpdateRoleId: values.isCheck.role,
            responseId: values.responseId,
            isUpdateResponseId: values.isCheck.response,
            statusId: values.statusId,
            isUpdateStatusId: values.isCheck.status,
            description: values.description,
            isUpdateDescription: values.isCheck.description,
            solution: values.solution,
            isUpdateSolution: values.isCheck.solution,
            licenseeType: values.licenseeId,
            isUpdateLicenseeType: values.isCheck.licensee,
            isReviewed: values.isCheck.reviewed,
            review: values.review,
            isUpdateReview: values.isCheck.reviewed,
            autoField: values.autoGenerated,
            isUpdateAutoField: values.isCheck.autoGenerated,
            communicationId: values.communicationToolIds,
            isUpdateCommunicationId: values.isCheck.communication,
            products: getProductParams(values.productIds.length > 0 ? values.productIds.split(',') : [],
                values.subProductIds.length > 0 ? values.subProductIds.split(',') : [],
                values.betTypeIds.length > 0 ? values.betTypeIds.split(',') : [],
                this.state.settings),
            isUpdateProduct: values.isCheck.product,
            categories: getCategoryParams(values.mainCategoryIds.split(','), values.subCategoryIds.split(','), this.state.settings.subCategories),
            isUpdateCategory: values.isCheck.mainCategory,
            noInquiries: values.noInquiries === '' ? 0 : parseInt(values.noInquiries, 10),
            isUpdateNoInquiries: values.isCheck.inquiry,
            updateReviewedMode: this.reviewMode(values)
        };
        this.confirmEditMultipleLogs(params);
    };

    reviewMode = values => {
        if (!this.state.hasReviewFeedbackPermission) {
            return 0;
        } else {
            if (!values.isReviewed) {
                return 2;
            } else {
                return 1;
            }
        }
    };

    confirmEditMultipleLogs = params => {
        this.setState({
            confirmEditMultipleLogsDialog: { show: true, params }
        });
    };

    handleCloseConfirmEditMultipleLogsDialog = () => {
        this.setState({
            confirmEditMultipleLogsDialog: { show: false }
        });
        this.formik.setSubmitting(false);
    };

    handleConfirmEditMultipleLogs = () => {
        const { params } = this.state.confirmEditMultipleLogsDialog;
        this.setState({
            confirmEditMultipleLogsDialog: { show: false }
        });
        this.handleEditMultipleLogs(params);
    };

    handleEditMultipleLogs = async params => {
        Site.blockUI();
        const url = Site.resolveClientUrl('MultipleLogs/EditMultipleLogs');
        await DataService.postDataAsync(url, params).then(response => {
            if (response.data.isSuccessful) {
                this.setState({ editResult: response.data });
                setTimeout(() => {
                    this.props.onClose(true);
                }, 3000);
            } else {
                this.formik.setSubmitting(false);
            }
        }).then(() => Site.unblockUI());
    };

    initFormik = (communicationLog, settings) => {
        const communicationSettings = this.getCommunicationSettings(communicationLog, settings);
        const usernames = this.state.feedbackArr.map(x => x.username).join(' ,');
        const init = getInitFormik(communicationLog, communicationSettings, usernames);
        return init;
    };

    render() {
        const { communication, settings, confirmEditMultipleLogsDialog } = this.state;
        if (communication === null || settings === null) {
            return null;
        }

        return (
            <div>
                <Modal show className="edit-multiple-log" dialogAs={DraggableModalDialog}
                    backdrop="static" keyboard={false} size="xl" centered
                    onHide={() => this.props.onClose(false)}
                >
                    <Modal.Header closeButton>
                        <Modal.Title as="div">{LangHelper.getResource('EditMultipleLogs')}</Modal.Title>
                    </Modal.Header>
                    <Formik
                        innerRef={el => this.formik = el}
                        initialValues={communication}
                        validate={values => getValidateFormik(values, settings)}
                        onSubmit={this.handleSubmit}
                    >
                        {this.renderForm}
                    </Formik>
                </Modal>
                {
                    confirmEditMultipleLogsDialog.show &&
                    <SweetModalDialog size="lg"
                        title={LangHelper.getResource('ConfirmMultipleUpdates')}
                        contents={<div>{LangHelper.getResource('ConfirmEditMultipleLogsContent')}</div>}
                        buttons={[
                            <Button variant="primary" size="sm" onClick={this.handleConfirmEditMultipleLogs}>
                                {LangHelper.getResource('OK')}
                            </Button>,
                            <Button variant="primary" size="sm" onClick={this.handleCloseConfirmEditMultipleLogsDialog}>
                                {LangHelper.getResource('Cancel')}
                            </Button>
                        ]}
                        onClose={this.handleCloseConfirmEditMultipleLogsDialog}
                    />
                }
            </div>
        );
    }
}

export default EditMultipleLogs;